bool to_will_alias(
    const Tensor& self,
    std::optional<ScalarType> dtype,
    std::optional<Layout> layout,
    std::optional<Device> device,
    bool copy,
    std::optional<c10::MemoryFormat> optional_memory_format) {
  auto memory_format = optional_memory_format.value_or(MemoryFormat::Preserve);

  return is_null_or_equal_to(dtype, self.dtype().toScalarType()) &&
      is_null_or_equal_to(layout, self.layout()) &&
      is_null_or_equal_to(device, self.device()) && !copy &&
      (memory_format == MemoryFormat::Preserve ||
       self.suggest_memory_format() == memory_format);
}

static inline Tensor to_impl(
    const Tensor& self,
    std::optional<ScalarType> dtype,
    std::optional<Layout> layout,
    std::optional<Device> device,
    std::optional<bool> pin_memory,
    bool non_blocking,
    bool copy,
    std::optional<c10::MemoryFormat> optional_memory_format) {
  // fast path
  if (to_will_alias(
          self, dtype, layout, device, copy, optional_memory_format)) {
    return self;
  }
  return at::_to_copy(
      self,
      dtype,
      layout,
      device,
      pin_memory,
      non_blocking,
      optional_memory_format);

def rank_internal(input, name=None, optimize=True):
  # pylint: disable=redefined-builtin
  """Returns the rank of a tensor.

  Args:
    input: A `Tensor` or `SparseTensor`.
    name: A name for the operation (optional).
    optimize: if true, encode the rank as a constant when possible.

  Returns:
    A `Tensor` of type `int32`.
  """
  with ops.name_scope(name, "Rank", [input]) as name:
    if isinstance(
        input, (sparse_tensor.SparseTensor, sparse_tensor.SparseTensorValue)):
      return gen_array_ops.size(input.dense_shape, name=name)
    else:
      input = ops.convert_to_tensor(input)
      input_shape = input.get_shape()
      if optimize and input_shape.ndims is not None:
        return constant(input_shape.ndims, dtypes.int32, name=name)
      return gen_array_ops.rank(input, name=name)

def shape_internal(input, name=None, optimize=True, out_type=None):
  # pylint: disable=redefined-builtin
  """Returns the shape of a tensor.

  If `out_type` is not specified and the shape is fully known, then we look at
  the dimension values to determine whether to return an int32 or int64 tensor.
  If the shape is not fully known, we default to int32.

  Args:
    input: A `Tensor` or `SparseTensor`.
    name: A name for the operation (optional).
    optimize: if true, encode the shape as a constant when possible.
    out_type: (Optional) The specified output type of the operation (`int32` or
      `int64`). Defaults to tf.int32.

  Returns:
    A `Tensor` of type `out_type`.

  """
  with ops.name_scope(name, "Shape", [input]) as name:
    if isinstance(
        input, (sparse_tensor.SparseTensor, sparse_tensor.SparseTensorValue)):
      if not out_type:
        out_type = dtypes.int32
      return gen_math_ops.cast(input.dense_shape, out_type)
    else:
      if not context.executing_eagerly():
        input = ops.convert_to_tensor(input)
        input_shape = input.get_shape()
        if optimize and input_shape.is_fully_defined():
          # For fully defined shapes, if the out_type is not specified, we pick
          # int32 / int64 based on the actual values.
          if not out_type:
            return constant_op._tensor_shape_tensor_conversion_function(  # pylint: disable=protected-access
                input_shape)
          return constant(input_shape.as_list(), out_type, name=name)
      if not out_type:
        out_type = dtypes.int32
      return gen_array_ops.shape(input, name=name, out_type=out_type)

@ops.RegisterGradient("Cast")
def _CastGrad(op: ops.Operation, grad):
  t = [
      dtypes.float16, dtypes.float32, dtypes.float64, dtypes.bfloat16,
      dtypes.complex64, dtypes.complex128
  ]
  src_type = op.inputs[0].dtype.base_dtype
  dst_type = grad.dtype.base_dtype
  if src_type in t and dst_type in t:
    return math_ops.cast(grad, src_type)
  else:
    return None

@ops.RegisterGradient("Add")
@ops.RegisterGradient("AddV2")
def _AddGrad(op: ops.Operation, grad):
  """Gradient for Add."""
  y = op.inputs[1]
  try:
    skip_input_indices = op.skip_input_indices or ()
    if 1 in skip_input_indices and _IsScalar(y):
      return grad, None
  except AttributeError:
    # No gradient skipping, so do the full gradient computation
    skip_input_indices = ()

  x = op.inputs[0]
  if isinstance(grad, tensor.Tensor) and _ShapesFullySpecifiedAndEqual(
      x, y, grad
  ):
    return grad, grad

  gx = None if 0 in skip_input_indices else grad
  gy = None if 1 in skip_input_indices else grad
  return _ReduceGradientArgs(x, y, gx, gy)

@ops.RegisterGradient("Reshape")
def _ReshapeGrad(op: ops.Operation, grad):
  """Defines the gradient for `array_ops.reshape()`."""
  input_shape = op.inputs[0].shape
  if input_shape.rank is not None and not input_shape.is_fully_defined():
    # If only one dimension is undefined, we can use a wildcard dimension in
    # the argument to `reshape()` to avoid creating a data dependency via
    # a dynamic `shape()` operation.
    input_shape_as_list = input_shape.as_list()
    undefined_dims = []
    has_zero_dim = False
    for i, dim in enumerate(input_shape_as_list):
      if dim is None:
        undefined_dims.append(i)
      elif dim == 0:
        # When the tensor has zero elements, the wildcard dimension
        # is underspecified, and `reshape()` will arbitrarily set the unknown
        # to `1`, triggering shape errors downstream.
        has_zero_dim = True
    if len(undefined_dims) == 1 and not has_zero_dim:
      input_shape_as_list[undefined_dims[0]] = -1
      return [
          array_ops.reshape(
              _IndexedSlicesToTensorNoWarning(grad), input_shape_as_list
          ),
          None,
      ]
  return [
      array_ops.reshape(
          _IndexedSlicesToTensorNoWarning(grad), array_ops.shape(op.inputs[0])
      ),
      None,
  ]

@ops.RegisterGradient("TensorScatterUpdate")
def _TensorScatterUpdateGrad(op: ops.Operation, grad):
  indices = op.inputs[1]
  updates_grad = array_ops.gather_nd(
      grad,
      indices,
  )
  tensor_grad = array_ops.tensor_scatter_update(
      array_ops.identity(grad),
      indices,
      array_ops.zeros_like(op.inputs[2], dtype=grad.dtype),
  )
  return [tensor_grad, None, updates_grad]
